mapper.select:
select m.*,
       t.name_spell tournamentNameEn,t.name tournamentName
from   third_match_info m LEFT JOIN third_sport_tournament t ON m.tournament_id = t.id
where  m.modify_time >= #{beginTime}

    and    m.modify_time <= #{endTime}


    and    m.data_source_code <= #{dataSourceCode}

order by m.modify_time,m.id

select m.*,
       mt.id relation_id,mt.match_id relation_match_id,mt.team_id relation_team_id,
       mt.match_position relation_match_position,mt.team_name_record relation_team_name_record,mt.remark relation_remark
from   third_match_info m left join third_match_team_relation mt on m.id = mt.match_id
where  m.data_source_code = #{dataSourceCode}
and    m.third_match_source_id = #{thirdMatchSourceId}

select id from third_match_team_relation
where match_id not in( select id from third_match_info)
limit #{num}
